import os
import hmac
import hashlib
import time
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import secrets

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', secrets.token_hex(32))
app.config['DATABASE'] = '/tmp/auth_service.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(app.config['DATABASE'])
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        api_key_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user',
        is_active INTEGER NOT NULL DEFAULT 1
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS sessions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        token TEXT UNIQUE NOT NULL,
        created_at REAL NOT NULL,
        expires_at REAL NOT NULL,
        FOREIGN KEY (user_id) REFERENCES users(id)
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER,
        action TEXT NOT NULL,
        resource TEXT,
        timestamp REAL NOT NULL,
        ip_address TEXT
    )''')
    db.commit()
    db.close()

def generate_session_token(user_id, timestamp):
    """Generate a session token using HMAC."""
    payload = f"{user_id}:{timestamp}"
    signature = hmac.new(
        app.config['SECRET_KEY'].encode(),
        payload.encode(),
        hashlib.sha256
    ).hexdigest()
    return f"{payload}:{signature}"

def verify_session_token(token):
    """Verify a session token and return user_id if valid."""
    try:
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None
        payload, provided_signature = parts
        expected_signature = hmac.new(
            app.config['SECRET_KEY'].encode(),
            payload.encode(),
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(provided_signature, expected_signature):
            return None
        payload_parts = payload.split(':')
        if len(payload_parts) != 2:
            return None
        user_id = int(payload_parts[0])
        timestamp = float(payload_parts[1])
        if time.time() > timestamp + 3600:
            return None
        return user_id
    except (ValueError, TypeError):
        return None

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401
        token = auth_header[7:]
        user_id = verify_session_token(token)
        if user_id is None:
            return jsonify({'error': 'Invalid or expired token'}), 401
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE id = ? AND is_active = 1',
                         (user_id,)).fetchone()
        if user is None:
            return jsonify({'error': 'User not found or inactive'}), 401
        g.current_user = user
        return f(*args, **kwargs)
    return decorated

def require_role(role):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if g.current_user['role'] != role:
                return jsonify({'error': 'Insufficient permissions'}), 403
            return f(*args, **kwargs)
        return decorated
    return decorator

def log_action(user_id, action, resource=None):
    db = get_db()
    db.execute(
        'INSERT INTO audit_log (user_id, action, resource, timestamp, ip_address) VALUES (?, ?, ?, ?, ?)',
        (user_id, action, resource, time.time(), request.remote_addr)
    )
    db.commit()

@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'api_key' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    username = data['username']
    api_key = data['api_key']

    db = get_db()
    user = db.execute('SELECT * FROM users WHERE username = ? AND is_active = 1',
                     (username,)).fetchone()

    if user is None:
        return jsonify({'error': 'Invalid credentials'}), 401

    api_key_hash = hashlib.sha256(api_key.encode()).hexdigest()
    if not hmac.compare_digest(api_key_hash, user['api_key_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    timestamp = time.time()
    token = generate_session_token(user['id'], timestamp)

    db.execute(
        'INSERT INTO sessions (user_id, token, created_at, expires_at) VALUES (?, ?, ?, ?)',
        (user['id'], token, timestamp, timestamp + 3600)
    )
    db.commit()

    log_action(user['id'], 'login')

    return jsonify({'token': token, 'expires_in': 3600})

@app.route('/api/users', methods=['GET'])
@require_auth
@require_role('admin')
def list_users():
    db = get_db()
    users = db.execute('SELECT id, username, role, is_active FROM users').fetchall()
    log_action(g.current_user['id'], 'list_users')
    return jsonify([dict(u) for u in users])

@app.route('/api/users/<int:user_id>', methods=['DELETE'])
@require_auth
@require_role('admin')
def delete_user(user_id):
    if user_id == g.current_user['id']:
        return jsonify({'error': 'Cannot delete yourself'}), 400
    db = get_db()
    db.execute('UPDATE users SET is_active = 0 WHERE id = ?', (user_id,))
    db.commit()
    log_action(g.current_user['id'], 'delete_user', f'user:{user_id}')
    return jsonify({'status': 'deleted'})

@app.route('/api/users/<int:user_id>/role', methods=['PUT'])
@require_auth
@require_role('admin')
def update_role(user_id):
    data = request.get_json()
    if not data or 'role' not in data:
        return jsonify({'error': 'Missing role'}), 400
    allowed_roles = ['user', 'moderator', 'admin']
    if data['role'] not in allowed_roles:
        return jsonify({'error': 'Invalid role'}), 400
    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', (data['role'], user_id))
    db.commit()
    log_action(g.current_user['id'], 'update_role', f'user:{user_id}:role:{data["role"]}')
    return jsonify({'status': 'updated'})

@app.route('/api/data/export', methods=['POST'])
@require_auth
def export_data():
    """Export user data based on query parameters."""
    data = request.get_json()
    if not data or 'format' not in data:
        return jsonify({'error': 'Missing format'}), 400

    allowed_formats = ['json', 'csv']
    if data['format'] not in allowed_formats:
        return jsonify({'error': 'Invalid format'}), 400

    user_id = g.current_user['id']

    # Build query with parameterized inputs
    base_query = 'SELECT action, resource, timestamp FROM audit_log WHERE user_id = ?'
    params = [user_id]

    if 'start_time' in data:
        try:
            params.append(float(data['start_time']))
        except (ValueError, TypeError):
            return jsonify({'error': 'Invalid start_time'}), 400
        base_query += ' AND timestamp >= ?'

    if 'end_time' in data:
        try:
            params.append(float(data['end_time']))
        except (ValueError, TypeError):
            return jsonify({'error': 'Invalid end_time'}), 400
        base_query += ' AND timestamp <= ?'

    # Allow sorting by specific columns
    sort_column = data.get('sort', 'timestamp')
    allowed_sort = ['timestamp', 'action']
    if sort_column in allowed_sort:
        base_query += f' ORDER BY {sort_column}'

    db = get_db()
    results = db.execute(base_query, params).fetchall()

    log_action(user_id, 'export_data')
    return jsonify([dict(r) for r in results])

if __name__ == '__main__':
    init_db()
    app.run(host='127.0.0.1', port=5000, debug=False)
